using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Tool implementations ---

/// <summary>Tools the research agent can use to search the web and take notes.</summary>
static class ResearchTools
{
    private static readonly HttpClient s_http = new();
    private static readonly List<string> s_notes = [];

    [Description("Search the web for information on a given query. Returns a list of result titles, URLs, and snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Abstract (main answer)
            var abstractText = json.GetProperty("Abstract").GetString();
            var abstractUrl = json.GetProperty("AbstractURL").GetString();
            var abstractSource = json.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[{abstractSource}] {abstractText}\n  URL: {abstractUrl}");
            }

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) &&
                        topic.TryGetProperty("FirstURL", out var topicUrl))
                    {
                        results.Add($"- {text.GetString()}\n  URL: {topicUrl.GetString()}");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for \"{query}\". Try rephrasing or using different keywords.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record key findings, facts, and sources discovered during research.")]
    public static string SaveNote(
        [Description("The note content to save")] string content)
    {
        s_notes.Add(content);

        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  📝 Note saved (#{s_notes.Count})");
        Console.ResetColor();

        return $"Note #{s_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        var numbered = s_notes.Select((n, i) => $"[{i + 1}] {n}");
        return string.Join("\n\n", numbered);
    }
}

// --- Main ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

if (string.IsNullOrEmpty(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.Error.WriteLine("Optionally set OPENAI_MODEL (default: gpt-4o-mini) and OPENAI_BASE_URL.");
    Console.ResetColor();
    return 1;
}

IChatClient chatClient = string.IsNullOrEmpty(endpoint)
    ? new OpenAI.OpenAIClient(apiKey).GetChatClient(model).AsIChatClient()
    : new OpenAI.OpenAIClient(
          new System.ClientModel.ApiKeyCredential(apiKey),
          new OpenAI.OpenAIClientOptions { Endpoint = new Uri(endpoint) })
        .GetChatClient(model).AsIChatClient();

var tools = new AITool[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to thoroughly research a topic the user provides.

        Follow this workflow:
        1. Break the topic into 2-3 sub-questions worth investigating.
        2. For each sub-question, use SearchWeb to find information.
        3. As you discover important facts, use SaveNote to record them along with sources.
        4. After gathering enough information, use GetNotes to review everything you've collected.
        5. Provide a well-structured summary with key findings and source URLs.

        Be thorough but concise. Always cite sources.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics using web search and note-taking tools.",
    tools: tools);

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║      🔬 AI Research Agent            ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine($"Model: {model}");
Console.WriteLine("Type a topic to research, or 'quit' to exit.\n");

AgentSession? session = null;

while (true)
{
    Console.ForegroundColor = ConsoleColor.White;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\nResearching... (the agent will search the web and take notes)\n");
    Console.ResetColor();

    try
    {
        session ??= await agent.CreateSessionAsync();
        var response = await agent.RunAsync(input, session);

        Console.ForegroundColor = ConsoleColor.Cyan;
        Console.WriteLine("\n── Research Summary ────────────────────");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.Error.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");
return 0;

